// URL/metadata checker with expected values.
//
// Reads docs/package-1/expectations.json (generated by scripts/inventory.mjs),
// crawls every target UA/EN URL and verifies:
//   status · redirect target (Location + required #fragment + destination 200,
//   single hop) · canonical (full absolute URL) · title · description · H1 ·
//   <html lang> · robots meta · X-Robots-Tag · hreflang declarations and
//   reciprocity by source page language · no raw i18n keys in visible text.
//
// Rules (approved Package 2 spec):
//   - canonical/hreflang compared as full absolute URLs;
//   - hreflang reciprocity: UA page declaring hreflang "en" must be answered
//     on the EN page by hreflang "uk" → UA URL (and vice versa). Pairs are
//     enforced only while BOTH pages return 200 — no false counterparts;
//   - an active redirect's destination must return 200; 404/500 is FAIL.
//     Same rules for `redirect` entries and `redirectPlannedTo`. Planned
//     redirects are enforced only when the expectation marks them active
//     (`redirectActive: true` — flipped when the target page is live);
//   - category redirects keep `#cases`: the fragment must appear in
//     Location. Actual scrolling + header offset → browser scenario.
//
// Modes:
//   --mode baseline     snapshot of the CURRENT system; records deviations,
//                       always exits 0 (baseline separated from acceptance).
//   --mode acceptance   enforces expectations for the selected phase;
//                       any violation → FAIL and exit code 1.
//   --phase all|current|target   (default all)
//
// Usage:
//   node scripts/check-urls.mjs --base http://localhost:3011 --mode baseline
//   node scripts/check-urls.mjs --base http://localhost:3011 --mode acceptance --phase current
import fs from "node:fs";
import path from "node:path";
import {
  normalizeAbsUrl,
  splitFragment,
  checkCanonical,
  checkHreflangDeclarations,
  checkHreflangReciprocal,
  checkRedirect,
  checkOgImage,
  measureImageBuffer,
} from "./lib/urlchecks.mjs";

const ROOT = process.cwd();
const args = process.argv.slice(2);
const getArg = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const BASE = getArg("--base", "http://localhost:3011").replace(/\/$/, "");
const MODE = getArg("--mode", "baseline");
const PHASE = getArg("--phase", "all");
const OUT = getArg("--out", path.join(ROOT, "docs", "package-1", `check-${MODE}.json`));
const EXPECT_PATH = path.join(ROOT, "docs", "package-1", "expectations.json");
const ORIGIN = "https://freelance-ua.agency";

if (!["baseline", "acceptance"].includes(MODE)) {
  console.error(`unknown --mode "${MODE}" (expected baseline|acceptance)`);
  process.exit(2);
}
if (!fs.existsSync(EXPECT_PATH)) {
  console.error("expectations.json not found — run `node scripts/inventory.mjs` first");
  process.exit(2);
}
const { entries } = JSON.parse(fs.readFileSync(EXPECT_PATH, "utf8"));
const selected = entries.filter((e) => PHASE === "all" || e.phase === PHASE);

const htmlDecode = (s) =>
  s == null ? s : s.replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&nbsp;/g, " ")
    .trim();

async function fetchPage(url) {
  const res = await fetch(url, { redirect: "manual" });
  const out = { status: res.status, location: res.headers.get("location"), xRobotsTag: res.headers.get("x-robots-tag") };
  if (res.status === 200) out.html = await res.text();
  return out;
}

async function statusOf(urlPath) {
  try {
    const res = await fetch(`${BASE}${urlPath}`, { redirect: "manual" });
    return res.status;
  } catch {
    return 0;
  }
}

function analyzeHtml(html) {
  const visible = html
    .replace(/<script[\s\S]*?<\/script>/g, " ")
    .replace(/<style[\s\S]*?<\/style>/g, " ")
    .replace(/<[^>]+>/g, " ");
  return {
    lang: html.match(/<html[^>]*\slang="([^"]+)"/)?.[1] ?? null,
    title: htmlDecode(html.match(/<title>([^<]*)<\/title>/)?.[1] ?? null),
    description: htmlDecode(html.match(/<meta name="description" content="([^"]*)"/)?.[1] ?? null),
    canonicals: [...html.matchAll(/<link rel="canonical" href="([^"]+)"/g)].map((m) => m[1]),
    robotsMeta: html.match(/<meta name="robots" content="([^"]+)"/)?.[1] ?? null,
    h1Count: (html.match(/<h1[\s>]/g) || []).length,
    h1: htmlDecode((html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/) || [, ""])[1].replace(/<[^>]+>/g, " ").replace(/\s+/g, " ")),
    hreflang: [...html.matchAll(/<link rel="alternate" href[Ll]ang="([^"]+)" href="([^"]+)"/g)].map((m) => ({ lang: m[1], href: m[2] })),
    ogTitle: htmlDecode(html.match(/property="og:title" content="([^"]*)"/)?.[1] ?? null),
    ogDescription: htmlDecode(html.match(/property="og:description" content="([^"]*)"/)?.[1] ?? null),
    ogUrl: html.match(/property="og:url" content="([^"]*)"/)?.[1] ?? null,
    ogLocale: html.match(/property="og:locale" content="([^"]*)"/)?.[1] ?? null,
    ogImage: {
      url: html.match(/property="og:image" content="([^"]*)"/)?.[1] ?? null,
      width: html.match(/property="og:image:width" content="([^"]*)"/)?.[1] ?? null,
      height: html.match(/property="og:image:height" content="([^"]*)"/)?.[1] ?? null,
      type: html.match(/property="og:image:type" content="([^"]*)"/)?.[1] ?? null,
    },
    twitterCard: html.match(/name="twitter:card" content="([^"]*)"/)?.[1] ?? null,
    twitterTitle: htmlDecode(html.match(/name="twitter:title" content="([^"]*)"/)?.[1] ?? null),
    twitterDescription: htmlDecode(html.match(/name="twitter:description" content="([^"]*)"/)?.[1] ?? null),
    twitterImage: html.match(/name="twitter:image" content="([^"]*)"/)?.[1] ?? null,
    rawKeys: [...new Set((visible.match(/\b(?:itCases|designCases|videoCases|nav|hero|services|cases|partners|footer|process|pricing|testimonial|why|contact|trusted|partnership|header)\.[A-Za-z0-9_.]+/g) || []))].slice(0, 20),
  };
}

/**
 * Read the local file behind an og:image URL and measure it.
 * Returns null for remote/missing files — the rules then fall back to
 * completeness only (see checkOgImage).
 */
function measureOgImageFile(url) {
  try {
    const parsed = new URL(url, ORIGIN);
    if (parsed.host !== new URL(ORIGIN).host) return null;
    const clean = decodeURIComponent(parsed.pathname);
    const filePath = path.join(ROOT, "public", clean.replace(/^\//, ""));
    if (!fs.existsSync(filePath)) return null;
    return measureImageBuffer(fs.readFileSync(filePath));
  } catch {
    return null;
  }
}

/* ───────────── crawl ───────────── */

const results = [];
const fatal = [];
for (const entry of selected) {
  const url = `${BASE}${entry.path}`;
  try {
    const res = await fetchPage(url);
    const row = { ...entry, actual: { status: res.status, location: res.location, xRobotsTag: res.xRobotsTag } };
    row.checks = [];

    if (entry.kind === "redirect") {
      // Active redirect: status + Location (with required fragment) + final
      // destination must be a working page (200).
      const { path: destPath } = splitFragment(entry.to ?? "");
      const destUrl = new URL(destPath, ORIGIN).pathname;
      const destStatus = await statusOf(destUrl);
      row.checks.push(...checkRedirect(
        { status: res.status, location: res.location },
        { statuses: entry.status ?? [301, 308], to: entry.to },
        destStatus,
      ));
      results.push(row);
      continue;
    }

    // kind === "page"
    const planned = entry.redirectPlannedTo ?? null;
    const plannedActive = MODE === "acceptance" && planned && entry.redirectActive === true;
    if (plannedActive) {
      const { path: destPath } = splitFragment(planned);
      const destStatus = await statusOf(destPath);
      row.checks.push(...checkRedirect(
        { status: res.status, location: res.location },
        { statuses: [301, 308], to: planned },
        destStatus,
      ));
      results.push(row);
      continue;
    }
    if (planned && MODE === "acceptance" && entry.redirectActive !== true) {
      row.plannedRedirect = { to: planned, enforced: false, note: "redirect not active yet (Package 3)" };
    }

    row.checks.push({ name: "status", ok: res.status === 200, expected: 200, actual: res.status });
    if (res.status !== 200) {
      results.push(row);
      continue;
    }
    const a = analyzeHtml(res.html);

    row.checks.push({ name: "canonical-count", ok: a.canonicals.length === 1, expected: 1, actual: a.canonicals.length });
    if (a.canonicals.length === 1) row.checks.push(checkCanonical(a.canonicals[0], entry.canonical));

    row.checks.push({ name: "lang", ok: a.lang === entry.lang, expected: entry.lang, actual: a.lang });

    const titlePresent = !!(a.title && a.title.trim());
    row.checks.push({ name: "title-present", ok: titlePresent, actual: a.title });
    if (entry.title != null) row.checks.push({ name: "title-match", ok: a.title === htmlDecode(entry.title), expected: htmlDecode(entry.title), actual: a.title });

    const descPresent = !!(a.description && a.description.trim());
    row.checks.push({ name: "description-present", ok: descPresent, actual: a.description ? `${a.description.slice(0, 60)}…` : null });
    if (entry.description != null) row.checks.push({ name: "description-match", ok: a.description === htmlDecode(entry.description), expected: htmlDecode(entry.description), actual: a.description });

    row.checks.push({ name: "h1-single", ok: a.h1Count === 1 && a.h1.length > 0, expected: 1, actual: a.h1Count, text: a.h1 });
    if (entry.h1 != null) row.checks.push({ name: "h1-match", ok: a.h1 === htmlDecode(entry.h1), expected: htmlDecode(entry.h1), actual: a.h1 });

    const robotsBad = a.robotsMeta ? /noindex/i.test(a.robotsMeta) : false;
    row.checks.push({ name: "robots-meta", ok: !robotsBad, actual: a.robotsMeta });
    const xrtBad = res.xRobotsTag ? /noindex/i.test(res.xRobotsTag) : false;
    row.checks.push({ name: "x-robots-tag", ok: !xrtBad, actual: res.xRobotsTag });

    row.checks.push({ name: "no-raw-i18n-keys", ok: a.rawKeys.length === 0, actual: a.rawKeys });

    // Bilingual pair pages own a complete, self-consistent social card set:
    // og:url must be the page's own canonical; og/twitter titles and
    // descriptions must match the page; twitter:card must exist.
    if (entry.bilingualPair) {
      row.checks.push({
        name: "og-url",
        ok: !!a.ogUrl && normalizeAbsUrl(a.ogUrl) === normalizeAbsUrl(entry.canonical),
        expected: normalizeAbsUrl(entry.canonical),
        actual: a.ogUrl ? normalizeAbsUrl(a.ogUrl) : null,
      });
      row.checks.push({ name: "og-title-present", ok: !!a.ogTitle, actual: a.ogTitle });
      if (entry.title != null) {
        row.checks.push({ name: "og-title-match", ok: a.ogTitle === htmlDecode(entry.title), expected: htmlDecode(entry.title), actual: a.ogTitle });
      }
      row.checks.push({ name: "og-description-present", ok: !!a.ogDescription, actual: a.ogDescription ? `${a.ogDescription.slice(0, 60)}…` : null });
      if (entry.description != null) {
        row.checks.push({ name: "og-description-match", ok: a.ogDescription === htmlDecode(entry.description), expected: htmlDecode(entry.description), actual: a.ogDescription });
      }
      const expectedOgLocale = entry.lang === "en" ? "en_US" : "uk_UA";
      row.checks.push({ name: "og-locale", ok: a.ogLocale === expectedOgLocale, expected: expectedOgLocale, actual: a.ogLocale });
      row.checks.push({ name: "og-image-present", ok: !!a.ogImage?.url, actual: a.ogImage?.url ?? null });
      row.checks.push({ name: "twitter-card", ok: a.twitterCard === "summary_large_image", expected: "summary_large_image", actual: a.twitterCard });
      row.checks.push({ name: "twitter-title-present", ok: !!a.twitterTitle, actual: a.twitterTitle });
      if (entry.title != null) {
        row.checks.push({ name: "twitter-title-match", ok: a.twitterTitle === htmlDecode(entry.title), expected: htmlDecode(entry.title), actual: a.twitterTitle });
      }
      row.checks.push({ name: "twitter-description-present", ok: !!a.twitterDescription, actual: a.twitterDescription ? `${a.twitterDescription.slice(0, 60)}…` : null });
      if (entry.description != null) {
        row.checks.push({ name: "twitter-description-match", ok: a.twitterDescription === htmlDecode(entry.description), expected: htmlDecode(entry.description), actual: a.twitterDescription });
      }
      row.checks.push({ name: "twitter-image-present", ok: !!a.twitterImage, actual: a.twitterImage });
    }

    // Open Graph cover: properties must match the real file (or be absent).
    // The old check only proved that some og:image existed, so a card
    // declaring 1200×630 / image/jpeg for a 1536×1024 WebP still passed.
    if (a.ogImage?.url) {
      const actual = measureOgImageFile(a.ogImage.url);
      row.ogImage = a.ogImage;
      row.ogImageActual = actual;
      // Presence is already asserted for bilingual pages above; here only the
      // property rules (completeness + match with the real file) are added.
      row.checks.push(
        ...checkOgImage(a.ogImage, actual).filter((c) => c.name !== "og-image-present"),
      );
    }

    // hreflang declarations: only enforced when the counterpart is live
    row.hreflangActual = a.hreflang;
    if (entry.hreflang) {
      const [ukPath, enPath] = [entry.hreflang.uk, entry.hreflang.en];
      const ukStatus = await statusOf(ukPath ?? "/");
      const enStatus = await statusOf(enPath ?? "/en");
      row.counterpartStatus = { uk: ukStatus, en: enStatus };
      if (ukStatus === 200 && enStatus === 200) {
        row.checks.push(...checkHreflangDeclarations(a.hreflang, entry.hreflang, ORIGIN));
      } else {
        row.hreflangSkipped = "counterpart-not-ready";
      }
    }
    results.push(row);
  } catch (err) {
    fatal.push({ path: entry.path, error: String(err.message || err) });
    results.push({ ...entry, actual: { status: 0 }, checks: [{ name: "fetch", ok: false, error: String(err.message || err) }], fetchError: true });
  }
}

/* ───────────── global hreflang reciprocity (by source language) ───────────── */
// For every crawled 200 page that declares hreflang, the declared counterpart
// (same origin, 200) must carry the reciprocal link with the SOURCE page's
// language. Counterparts that are not 200 are skipped — no false pairs.
const pageRows = results.filter((r) => r.kind === "page" && r.actual?.status === 200);
const byPath = new Map(pageRows.map((r) => [r.path, r]));
const reciprocity = [];
for (const r of pageRows) {
  if (!r.hreflangActual?.length) continue;
  for (const h of r.hreflangActual) {
    let targetPath;
    try {
      targetPath = new URL(h.href, ORIGIN).pathname;
    } catch {
      reciprocity.push({ from: r.path, lang: h.lang, ok: false, reason: "unparseable-href", href: h.href });
      continue;
    }
    // href must stay on the main origin — a different domain fails
    try {
      const host = new URL(h.href, ORIGIN).host;
      if (host !== new URL(ORIGIN).host) {
        reciprocity.push({ from: r.path, lang: h.lang, ok: false, reason: "foreign-origin", href: h.href });
        continue;
      }
    } catch { /* keep going */ }
    const target = byPath.get(targetPath);
    const verdict = checkHreflangReciprocal(
      { path: r.path, lang: r.lang, hreflang: r.hreflangActual },
      target ? { path: target.path, lang: target.lang, status: target.actual.status, hreflang: target.hreflangActual } : null,
      ORIGIN,
    );
    reciprocity.push({ from: r.path, lang: h.lang, to: targetPath, ...verdict });
  }
}

/* ───────────── sitemap validation ───────────── */
// The sitemap must list exactly the ready (current-phase, 200) pages:
// no target-only URLs, no redirect sources, no missing canonical pages.
let sitemapResult;
try {
  const smRes = await fetch(`${BASE}/sitemap.xml`);
  const xml = await smRes.text();
  const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
  const locPaths = locs.map((u) => {
    try {
      const url = new URL(u);
      return url.host === new URL(ORIGIN).host ? url.pathname : `FOREIGN:${u}`;
    } catch {
      return `INVALID:${u}`;
    }
  });
  const currentPages = new Set(results.filter((r) => r.kind === "page" && r.phase === "current").map((r) => r.path));
  const statusByPath = new Map(results.map((r) => [r.path, r.actual?.status]));
  const foreignOrInvalid = locPaths.filter((p) => p.startsWith("FOREIGN:") || p.startsWith("INVALID:"));
  const normalizedLocs = locPaths.filter((p) => !p.startsWith("FOREIGN:") && !p.startsWith("INVALID:")).map((p) => (p.length > 1 && p.endsWith("/") ? p.slice(0, -1) : p) || "/");
  const unknownLocs = normalizedLocs.filter((p) => !currentPages.has(p));
  const not200 = normalizedLocs.filter((p) => statusByPath.get(p) !== 200);
  const missingFromSitemap = [...currentPages].filter((p) => !normalizedLocs.includes(p));
  sitemapResult = {
    status: smRes.status,
    contentType: smRes.headers.get("content-type"),
    urlCount: locs.length,
    hasLastmod: /<lastmod>/.test(xml),
    foreignOrInvalid,
    unknownLocs,
    not200,
    missingFromSitemap,
    // lastmod is intentionally absent (no reliable content dates) — a
    // reappeared lastmod (e.g. build timestamps) is a violation
    ok: smRes.status === 200 && foreignOrInvalid.length === 0 && unknownLocs.length === 0 && not200.length === 0 && missingFromSitemap.length === 0 && !/<lastmod>/.test(xml),
  };
} catch (err) {
  sitemapResult = { ok: false, error: String(err.message || err) };
}

/* ───────────── aggregate ───────────── */

const checkFailures = [];
for (const r of results) {
  for (const c of r.checks ?? []) {
    if (c.ok === false) checkFailures.push({ path: r.path, phase: r.phase, kind: r.kind, check: c.name, expected: c.expected, actual: c.actual, text: c.text, detail: c.detail, note: c.note });
  }
}
const reciprocityFailures = reciprocity.filter((x) => x.ok === false);
const reciprocitySkipped = reciprocity.filter((x) => x.ok === null);

const report = {
  mode: MODE,
  phase: PHASE,
  base: BASE,
  checkedAt: new Date().toISOString(),
  total: results.length,
  fatal,
  summary: {
    pages200: results.filter((r) => r.kind === "page" && r.actual?.status === 200).length,
    redirectsOk: results.filter((r) => (r.kind === "redirect" || r.plannedRedirect?.enforced) && (r.checks ?? []).every((c) => c.ok)).length,
    failures: checkFailures.length,
    reciprocityChecked: reciprocity.filter((x) => x.ok !== null).length,
    reciprocitySkippedNotReady: reciprocitySkipped.length,
    reciprocityFailures: reciprocityFailures.length,
    sitemapOk: sitemapResult?.ok ?? false,
  },
  checkFailures,
  reciprocityFailures,
  sitemap: sitemapResult,
  reciprocity,
  results,
};

fs.writeFileSync(OUT, JSON.stringify(report, null, 2));

/* ───────────── console ───────────── */

console.log(`mode=${MODE} phase=${PHASE} base=${BASE}`);
console.log(`  checked: ${report.total}`);
console.log(`  pages 200: ${report.summary.pages200}`);
console.log(`  redirects OK: ${report.summary.redirectsOk}`);
console.log(`  check failures: ${report.summary.failures}`);
console.log(`  hreflang reciprocity: checked ${report.summary.reciprocityChecked}, skipped(not ready) ${report.summary.reciprocitySkippedNotReady}, failed ${report.summary.reciprocityFailures}`);
console.log(`  sitemap: ${sitemapResult?.ok ? "OK" : "VIOLATION"} (${sitemapResult?.urlCount ?? "?"} urls${sitemapResult?.hasLastmod ? ", has lastmod" : ""}${sitemapResult?.unknownLocs?.length ? `, unknown: ${sitemapResult.unknownLocs.length}` : ""}${sitemapResult?.missingFromSitemap?.length ? `, missing: ${sitemapResult.missingFromSitemap.length}` : ""})`);
if (fatal.length) console.log(`  FATAL (fetch errors): ${fatal.length}`);
if (checkFailures.length) {
  const byName = {};
  for (const f of checkFailures) byName[f.check] = (byName[f.check] || 0) + 1;
  console.log(`  failures by check: ${JSON.stringify(byName)}`);
}
console.log(`report: ${path.relative(ROOT, OUT)}`);

if (MODE === "baseline") {
  if (fatal.length && fatal.length === report.total) {
    console.error("FATAL: no URL could be fetched — is the server running?");
    process.exit(2);
  }
  process.exit(0);
}

const failed = checkFailures.length > 0 || reciprocityFailures.length > 0 || fatal.length > 0 || !sitemapResult?.ok;
if (failed) {
  const extras = (sitemapResult?.ok ? 0 : 1) + fatal.length;
  console.error(`FAIL: ${checkFailures.length + reciprocityFailures.length + extras} violation(s)`);
  process.exit(1);
}
console.log("PASS");
process.exit(0);
